import time


class ConnectionPool:
    def __init__(self, factory, max_size, idle_timeout=60.0, clock=time.monotonic):
        self._factory = factory
        self._max_size = max_size
        self._idle_timeout = idle_timeout
        self._clock = clock
        self._idle = []
        self._active = set()

    def acquire(self):
        now = self._clock()
        while self._idle:
            conn, last_used = self._idle.pop()
            if now - last_used <= self._idle_timeout:
                self._active.add(conn)
                return conn

        if len(self._active) < self._max_size:
            conn = self._factory()
            self._active.add(conn)
            return conn

        return None

    def release(self, conn, healthy=True):
        if conn not in self._active:
            raise ValueError("Connection was not checked out from this pool")
        self._active.remove(conn)
        if healthy:
            self._idle.append((conn, self._clock()))

    @property
    def stats(self):
        return {
            "active": len(self._active),
            "idle": len(self._idle),
            "total": len(self._active) + len(self._idle)
        }
